{"className":""h-11 active:scale-100"","disabled":"{activePages.status === 'loading'}","onClick":"{() => {
                  const nextPage = activePages.pageNumber - 1
                  if (tab === 'providers') providerPages.showPreviousPage()
                  else showPreviousPage()
                  void navigate({ to: marketPath, resetScroll: false, search: carryMarketCompare(search, { ...indexedSearch(), view: tab, ...(nextPage > 1 ? { page: nextPage } : {}) }) })
                }}","type":""button"","variant":""secondary""}

{"aria-busy":"{pending || undefined}","className":""arc-identity-save"","disabled":"{pending || invalid || unchanged}","onClick":"{() => {
        setPending(true)
        setFeedback(undefined)
        void onRename({ businessId, name, requestKey: requestKeyRef.current ?? crypto.randomUUID() })
          .then((result) => {
            setFeedback(result)
            if (result.kind === 'updated') {
              setName(result.name)
              requestKeyRef.current = crypto.randomUUID()
            }
          })
          .catch((cause) => {
            captureClientExceptionOnClient(cause)
            setFeedback({ kind: 'refused', code: 'source_unavailable' })
          })
          .finally(() => setPending(false))
      }}","size":""md"","type":""button"","variant":""primary""}

