{"...0":"{...(compact ? { "aria-haspopup": "dialog" as const } : {})}","aria-controls":"{compact ? drawerId : sidebarId}","aria-expanded":"{compact ? mobileOpen : !collapsed}","aria-label":"{toggleLabel}","className":"{styles.toggle}","onClick":"{() => {
        if (compact) {
          setMobileOpen(true);
