{"aria-label":""Next example or drag to browse"","className":""arc-pdp-dragHandle"","onClick":"{event => {
          if (event.detail > 0 && dragged.current) { dragged.current = false; return }
          go(indexRef.current === count - 1 ? 0 : indexRef.current + 1)
        }}","onPointerCancel":"{() => { pointerStart.current = null; dragged.current = true }}","onPointerDown":"{event => {
          pointerStart.current = { x: event.clientX, y: event.clientY }
          dragged.current = false
          dragControls.start(event)
        }}","onPointerMove":"{event => {
          const start = pointerStart.current
          if (start !== null && Math.hypot(event.clientX - start.x, event.clientY - start.y) > 3) dragged.current = true
        }}","onPointerUp":"{() => { pointerStart.current = null }}","type":""button""}
